-- Soil Analysis GIS — Phase 10.4 Historical Data Import
-- H1 82 + H2 57 = 139 analytical samples/observations
-- H2 Anakapalle Site 3: 3 records excluded; preserved in historical_exclusions
USE soil_analysis_gis;
START TRANSACTION;

SELECT id,dataset_code,dataset_name,publication_year,status FROM historical_datasets WHERE dataset_code IN ('H1','H2') ORDER BY dataset_code;


-- H2 analytical records

-- Validation
SELECT hd.dataset_code,COUNT(hs.id) sample_count FROM historical_datasets hd LEFT JOIN historical_samples hs ON hs.dataset_id=hd.id WHERE hd.dataset_code IN ('H1','H2') GROUP BY hd.id,hd.dataset_code ORDER BY hd.dataset_code;
SELECT COUNT(*) observation_count FROM historical_observations ho JOIN historical_samples hs ON hs.id=ho.historical_sample_id WHERE hs.dataset_id IN (1,2);
SELECT COUNT(*) h2_exclusions FROM historical_exclusions WHERE dataset_id=2;
SELECT COUNT(*) h2_site3_imported FROM historical_samples WHERE dataset_id=2 AND mandal='Anakapalle' AND site_no=3;
-- Expected: H1=82, H2=57, observations=139, exclusions=3, H2 Site 3 imported=0
COMMIT;

-- Final counts
SELECT hd.dataset_code,COUNT(hs.id) sample_count FROM historical_datasets hd LEFT JOIN historical_samples hs ON hs.dataset_id=hd.id WHERE hd.dataset_code IN ('H1','H2') GROUP BY hd.id,hd.dataset_code ORDER BY hd.dataset_code;
SELECT COUNT(*) observation_count FROM historical_observations ho JOIN historical_samples hs ON hs.id=ho.historical_sample_id WHERE hs.dataset_id IN (1,2);
